      image: { "src": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Bobby_Broom_Trio_-_INNt%C3%B6ne_Jazzfestival_2013_Makaye_McCraven.jpg/960px-Bobby_Broom_Trio_-_INNt%C3%B6ne_Jazzfestival_2013_Makaye_McCraven.jpg", "page": "https://commons.wikimedia.org/wiki/File:Bobby_Broom_Trio_-_INNt%C3%B6ne_Jazzfestival_2013_Makaye_McCraven.jpg", "caption": "Makaya McCraven on drums with the Bobby Broom Trio at the INNtöne Jazzfestival, Diersbach, Austria, 18 May 2013, the year his weekly sessions at The Bedford began.", "credit": "Manfred Werner (Tsui)", "license": "CC BY-SA 3.0" },
